_table: Optional[Dict[int, bytes]] = None


def setup_packets() -> Dict[int, bytes]:
    """CRC-32 -> Vorbis setup packet (starts with 05 'vorbis'), decompressed once."""
    global _table
    if _table is None:
        raw = lzma.decompress(base64.b64decode(''.join(_XZ)))
        count = struct.unpack_from('<I', raw, 0)[0]
        table, p = {}, 4
        for _ in range(count):
            crc, size = struct.unpack_from('<II', raw, p)
            table[crc] = raw[p + 8:p + 8 + size]
            p += 8 + size
        _table = table
    return _table


def setup_packet(crc32: int) -> Optional[bytes]:
    return setup_packets().get(crc32 & 0xFFFFFFFF)
